import base64,hashlib,json,os,pathlib
raw=base64.b64decode('',validate=True);assert hashlib.sha256(raw).hexdigest()=='9e618246377f86ffd975ad0f90a8c029dd265c9e2bfb9344b391f59d7c4edb33'
assert os.getuid()==os.geteuid()==0
p=pathlib.Path('/home/jwk/memory-quick.sh');assert p.parent.resolve()==p.parent and not p.is_symlink()
if p.exists():assert p.is_file() and p.read_bytes()==raw,'Existing different file preserved'
else:
 with p.open('xb') as f:f.write(raw)
 os.chown(p,0,0);p.chmod(0o755)
print(json.dumps({'installed':str(p),'sha256':'9e618246377f86ffd975ad0f90a8c029dd265c9e2bfb9344b391f59d7c4edb33','benchmarkStarted':False}))
